#!/usr/bin/env node
/**
 * Generates the boundary rule set and the TypeScript path map FROM the module
 * registry.
 *
 *   node scripts/generate-boundary-rules.mjs           write the files
 *   node scripts/generate-boundary-rules.mjs --check   fail if they are stale
 *
 * The registry is the source of the rules; the checker is not. A hand edit of
 * a generated file fails --check, which is the generation step of negative
 * control 7: a package under modules/ with no registry entry, or a rule set
 * that has drifted from the registry, stops the build here rather than at the
 * checker.
 *
 * Outputs:
 *   .dependency-cruiser.cjs   the seven rules of P0.2, expressed as forbidden
 *                             dependencies between path patterns
 *   tsconfig.paths.json       @biztrust/<module> resolved to the contract path,
 *                             so the checker and the compiler read the same
 *                             edges before anything is built
 *
 * Exit codes: 0 written or fresh; 1 stale under --check, or the registry is
 * invalid; 2 an unforeseen defect in this script.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { createHash } from "node:crypto";
import { ROOT, REGISTRY_PATH, loadRegistry, RegistryError } from "./registry.mjs";
import { buildRules } from "./boundary-rules.mjs";

const DEPCRUISE_OUT = join(ROOT, ".dependency-cruiser.cjs");
const PATHS_OUT = join(ROOT, "tsconfig.paths.json");

/**
 * The content hash of the registry the configuration was generated from.
 *
 * Peer review F8: this used to be the last commit touching modules/modules.yaml,
 * which was empty before the first commit and never refreshed after, so it read
 * `uncommitted` permanently. A commit SHA is also the wrong thing to bind to -
 * it changes when any other file in that commit changes. A content hash of the
 * registry itself is stable, comparable, and is what the P0.2 design's owners
 * table actually needs: which registry produced these rules.
 *
 * It is compared by --check, unlike the revision line it replaces.
 */
function registryDigest() {
  // Carriage returns are stripped first: the same registry checked out on
  // Windows and on the CI runner must produce the same digest, or --check
  // fails on one platform and not the other.
  const CR = String.fromCharCode(13);
  const text = readFileSync(REGISTRY_PATH, "utf8").split(CR).join("");
  return createHash("sha256").update(text, "utf8").digest("hex");
}

function renderDepcruise(registry, rules) {
  const header = [
    "/**",
    " * GENERATED FILE - DO NOT EDIT.",
    " *",
    " * Generated by scripts/generate-boundary-rules.mjs from the module",
    " * registry. A hand edit fails `pnpm boundaries:check`.",
    " *",
    ` * Registry:          modules/modules.yaml`,
    ` * Registry version:  ${registry.version}`,
    ` * Registry sha256:   ${registryDigest()}`,
    ` * Modules:           ${registry.modules.length} registered, ` +
      `${registry.modules.filter((m) => m.package).length} with a package`,
    " *",
    " * To change a rule, change the registry or the generator, never this file.",
    " */",
    "",
  ].join("\n");

  const body = {
    forbidden: rules,
    options: {
      doNotFollow: { path: "node_modules" },
      exclude: { path: "(^|/)dist/|^tests/boundaries/fixtures/" },
      tsPreCompilationDeps: true,
      tsConfig: { fileName: "tsconfig.json" },
      enhancedResolveOptions: {
        exportsFields: ["exports"],
        conditionNames: ["import", "require", "node", "default", "types"],
        extensions: [".ts", ".js", ".mjs", ".cjs"],
      },
      reporterOptions: { text: { highlightFocused: true } },
    },
  };

  return `${header}module.exports = ${JSON.stringify(body, null, 2)};\n`;
}

function renderPaths(registry) {
  const paths = {};
  for (const m of registry.modules) {
    if (m.package !== true) continue;
    paths[`@biztrust/${m.name}`] = [`./modules/${m.name}/${m.contract}`];
  }
  paths["@biztrust/contracts"] = ["./packages/contracts/src/index.ts"];
  paths["@biztrust/observability"] = ["./packages/observability/src/index.ts"];

  return `${JSON.stringify(
    {
      _generated:
        "GENERATED by scripts/generate-boundary-rules.mjs from modules/modules.yaml. Do not edit.",
      _registryVersion: registry.version,
      compilerOptions: { baseUrl: ".", paths },
    },
    null,
    2,
  )}\n`;
}

function readOrNull(path) {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return null;
  }
}

function main() {
  const check = process.argv.includes("--check");
  let registry;
  try {
    registry = loadRegistry();
  } catch (error) {
    if (error instanceof RegistryError) {
      process.stderr.write(`BOUNDARY_GENERATION FAIL ${error.message}\n`);
      return 1;
    }
    throw error;
  }

  const outputs = [
    [DEPCRUISE_OUT, renderDepcruise(registry, buildRules(registry)), ".dependency-cruiser.cjs"],
    [PATHS_OUT, renderPaths(registry), "tsconfig.paths.json"],
  ];

  if (check) {
    const stale = [];
    for (const [path, wanted, label] of outputs) {
      const found = readOrNull(path);
      // Compared, not stripped. The old revision line was excluded from the
      // comparison because it changed per commit, which meant the one field
      // recording WHICH registry produced these rules was never checked. A
      // content hash is stable across commits, so it is compared like
      // everything else.
      if (found !== wanted) {
        stale.push(found === null ? `${label} is missing` : `${label} is stale`);
      }
    }
    if (stale.length > 0) {
      process.stderr.write(
        `BOUNDARY_GENERATION FAIL ${stale.join("; ")}. ` +
          `Run: node scripts/generate-boundary-rules.mjs\n`,
      );
      return 1;
    }
    process.stdout.write(
      `BOUNDARY_GENERATION PASS ${registry.modules.length} modules, generated files are current\n`,
    );
    return 0;
  }

  for (const [path, content, label] of outputs) {
    writeFileSync(path, content, "utf8");
    process.stdout.write(`wrote ${label}\n`);
  }
  return 0;
}

try {
  process.exitCode = main();
} catch (error) {
  process.stderr.write(`BOUNDARY_GENERATION FAIL validator defect: ${error?.stack ?? error}\n`);
  process.exitCode = 2;
}
